import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents rounds half to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(-0.5), 0);
});

test('roundCents ignores binary noise', () => {
  assert.equal(roundCents(124.49999999999999), 124);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(-5), '-€0.05');
});

test('parseEuros reads what people type', () => {
  assert.deepEqual(parseEuros('12'), { ok: true, value: 1200 });
  assert.deepEqual(parseEuros('12.5'), { ok: true, value: 1250 });
  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
});

test('RATES has EUR, USD, and GBP', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to USD', () => {
  const result = convert(100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 108);
});

test('convert EUR to GBP', () => {
  const result = convert(100, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 84);
});

test('convert EUR to EUR', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 100);
});

test('convert with rounding', () => {
  const result = convert(123, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 134);
});

test('convert unknown currency', () => {
  const result = convert(100, 'XYZ');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert zero amount', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert large amount', () => {
  const result = convert(1000000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1085000);
});

test('convert negative amount', () => {
  const result = convert(-100, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -108);
});

test('formatMoney EUR', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney USD', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney GBP', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney with thousands separator USD', () => {
  assert.equal(formatMoney(1234567, 'USD'), '$12,345.67');
});

test('formatMoney with thousands separator GBP', () => {
  assert.equal(formatMoney(1234567, 'GBP'), '£12,345.67');
});

test('formatMoney with negative amount EUR', () => {
  assert.equal(formatMoney(-5, 'EUR'), '-€0.05');
});

test('formatMoney with negative amount USD', () => {
  assert.equal(formatMoney(-5, 'USD'), '-$0.05');
});

test('formatMoney with negative amount GBP', () => {
  assert.equal(formatMoney(-5, 'GBP'), '-£0.05');
});

test('formatMoney zero EUR', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
});

test('formatMoney zero USD', () => {
  assert.equal(formatMoney(0, 'USD'), '$0.00');
});

test('formatMoney zero GBP', () => {
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('formatMoney small amount EUR', () => {
  assert.equal(formatMoney(1, 'EUR'), '€0.01');
});

test('formatMoney small amount USD', () => {
  assert.equal(formatMoney(1, 'USD'), '$0.01');
});

test('formatMoney small amount GBP', () => {
  assert.equal(formatMoney(1, 'GBP'), '£0.01');
});

test('formatMoney large amount EUR', () => {
  assert.equal(formatMoney(10000000, 'EUR'), '€100,000.00');
});

test('formatMoney large amount USD', () => {
  assert.equal(formatMoney(10000000, 'USD'), '$100,000.00');
});

test('formatMoney large amount GBP', () => {
  assert.equal(formatMoney(10000000, 'GBP'), '£100,000.00');
});

test('convert and formatMoney together', () => {
  const eurCents = 102850;
  const convertResult = convert(eurCents, 'USD');
  assert.equal(convertResult.ok, true);
  const formatted = formatMoney(convertResult.value, 'USD');
  assert.equal(formatted, '$1,115.90');
});

test('convert GBP and format', () => {
  const eurCents = 102850;
  const convertResult = convert(eurCents, 'GBP');
  assert.equal(convertResult.ok, true);
  const formatted = formatMoney(convertResult.value, 'GBP');
  assert.equal(formatted, '£866.72');
});

test('formatMoney all currencies same amount', () => {
  const eurAmount = 123456;
  const eurFormatted = formatMoney(eurAmount, 'EUR');
  const usdFormatted = formatMoney(eurAmount, 'USD');
  const gbpFormatted = formatMoney(eurAmount, 'GBP');
  assert.equal(eurFormatted, '€1,234.56');
  assert.equal(usdFormatted, '$1,234.56');
  assert.equal(gbpFormatted, '£1,234.56');
});

